    private static readonly Dictionary<string, string> Es = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " El control táctil también está activado.",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Ajustes → Información del teléfono → toca 7 veces «Número de compilación» (opciones para desarrolladores activadas).\n\n2. Conéctate a una red Wi-Fi. Ajustes → Sistema → Opciones para desarrolladores → activa «Depuración inalámbrica».\n\n3. Abre Shizuku → «Iniciar mediante depuración inalámbrica» → «Vincular». Shizuku muestra una notificación para introducir el código de vinculación.\n\n4. En las Opciones para desarrolladores, en «Depuración inalámbrica», toca «Vincular dispositivo con código de vinculación» e introduce el código en la notificación de Shizuku.\n\n5. Toca «Iniciar» en Shizuku. Listo: vuelve a N-Connect.",
        ["1. Shizuku installieren"] = "1. Instalar Shizuku",
        ["2. Shizuku starten"] = "2. Iniciar Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Permitir el acceso a N-Connect",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>La primera vez:</b> Mantén pulsado el pequeño <b>botón SYNC</b> redondo del mando hasta que las luces vayan de un lado a otro. N-Connect lo encuentra automáticamente: no tienes que tocar nada.<br><br><b>Después:</b> Basta con pulsar un botón y el mando se vuelve a conectar solo.<br><br><b>Joy-Con:</b> Conecta los dos uno tras otro. Se combinan automáticamente en un solo mando (se puede desactivar en los ajustes).<br><br><b>Importante:</b> Un mando solo recuerda <b>un</b> dispositivo. Si quieres volver a usarlo en la Switch 2, pulsa SYNC allí y después también en el móvil.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>No se encuentra el mando:</b> ¿Está activado el Bluetooth? ¿Has mantenido pulsado SYNC hasta que se muevan las luces? Si está conectado a la Switch o a un PC, desactiva primero el Bluetooth allí.<br><br><b>Conectado, pero el juego no responde:</b> En la página de mandos debe poner «Listo» arriba. Si pone «Shizuku no está iniciado», abre Shizuku y toca Iniciar.<br><br><b>La conexión se corta mientras juegas:</b> Excluye N-Connect de la optimización de batería (Ajustes → Aplicaciones → N-Connect → Batería → <i>Sin restricciones</i>).<br><br><b>Entradas dobles:</b> Si el control táctil también está activado y el juego admite mandos, desactiva el táctil.<br><br><b>El mando ya no se conecta solo:</b> Pulsa SYNC una vez y volverá a recordar este dispositivo.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Configurar directamente</b> coloca el repositorio en Kodi (mediante {0}). Después en Kodi: <b>Add-ons → Mis add-ons → Repositorio de add-ons → DevCatSKZ Repository → Activar</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Descargar</b> guarda el archivo en la carpeta Descargas. Después en Kodi:<br><b>1.</b> Ajustes → Sistema → Add-ons → activa <b>Fuentes desconocidas</b>.<br><b>2.</b> Add-ons → icono del paquete → <b>Instalar desde un archivo zip</b> → Download → <i>{0}</i>.<br><b>3.</b> «Instalar desde repositorio» → <b>DevCatSKZ Repository</b>.",
        ["A (unten)"] = "A (abajo)",
        ["ALLGEMEIN"] = "GENERAL",
        ["AUSGABE"] = "SALIDA",
