        ["DARSTELLUNG"] = "APARIENCIA",
        ["Damit N-Connect erkennt, welches Spiel gerade läuft, erlaube einmal „Zugriff auf Nutzungsdaten“. Die App liest damit nur den Namen der App im Vordergrund – keine Inhalte."] = "Para que N-Connect reconozca qué juego se está ejecutando, permite una vez el «Acceso a datos de uso». La app solo lee el nombre de la app en primer plano, ningún contenido.",
        ["Das Profil wird automatisch aktiv, solange „{0}“ läuft."] = "El perfil se activa automáticamente mientras «{0}» esté en ejecución.",
        ["Das Repository liegt jetzt in Kodi. Öffne Kodi und schalte es ein:\nAdd-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren.\n\nLäuft Kodi gerade, beende es vorher einmal ganz."] = "El repositorio ya está en Kodi. Abre Kodi y actívalo:\nAdd-ons → Mis add-ons → Repositorio de add-ons → DevCatSKZ Repository → Activar.\n\nSi Kodi está abierto, ciérralo por completo antes.",
        ["Deine Controller erscheinen als echter Xbox-Controller in allen Spielen und Emulatoren. Kein Root nötig – du richtest einmal die kostenlose App Shizuku ein."] = "Tus mandos aparecen como un mando de Xbox real en todos los juegos y emuladores. Sin root: configuras una vez la app gratuita Shizuku.",
        ["Der Knopf öffnet direkt den Schalter für „N-Connect Touch-Steuerung“ – einschalten und zurückkehren."] = "El botón abre directamente el interruptor de «Control táctil de N-Connect»: actívalo y vuelve.",
        ["Diagnose"] = "Diagnóstico",
        ["Die Touch-Steuerung ist eine Bedienungshilfe. Sie führt nur Berührungen aus und liest keine Inhalte vom Bildschirm."] = "El control táctil es un servicio de accesibilidad. Solo realiza toques y no lee ningún contenido de la pantalla.",
        ["Dieser Controller ist mit einem anderen Gerät gekoppelt (z. B. deiner Switch 2 oder einem PC). Drücke die SYNC-Taste, um ihn mit diesem Gerät zu verbinden."] = "Este mando está vinculado a otro dispositivo (p. ej. tu Switch 2 o un PC). Pulsa el botón SYNC para conectarlo a este dispositivo.",
        ["Direkt einrichten"] = "Configurar directamente",
        ["Direkt einrichten ging nicht – nutze „Herunterladen“."] = "No se pudo configurar directamente: usa «Descargar».",
        ["Download fehlgeschlagen – Internetverbindung prüfen."] = "La descarga ha fallado: comprueba la conexión a Internet.",
        ["Download fehlgeschlagen – bitte später erneut versuchen"] = "Descarga fallida – inténtalo de nuevo más tarde",
        ["Drück eine Taste – sie erscheint hier."] = "Pulsa un botón: aparecerá aquí.",
        ["Du kannst weitere Controller verbinden oder auf „Weiter“ tippen."] = "Puedes conectar más mandos o tocar «Siguiente».",
        ["Dunkel"] = "Oscuro",
        ["Echter Xbox-Controller für alle Spiele – ohne Root. Einmal kurz einrichten."] = "Mando de Xbox real para todos los juegos, sin root. Configuración rápida una sola vez.",
        ["Echter Xbox-Controller für alle Spiele. Nur auf gerooteten Geräten."] = "Mando de Xbox real para todos los juegos. Solo en dispositivos rooteados.",
        ["Eigene Tastenbelegungen, die automatisch zum laufenden Spiel passen."] = "Asignaciones de botones propias que se activan automáticamente con el juego.",
