    private static readonly Dictionary<string, string> Fr = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " Les commandes tactiles sont aussi activées.",
        [" · {0} MB"] = " · {0} Mo",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Paramètres → À propos du téléphone → appuyez 7× sur « Numéro de build » (options pour les développeurs activées).\n\n2. Connectez-vous à un réseau Wi-Fi. Paramètres → Système → Options pour les développeurs → activez « Débogage sans fil ».\n\n3. Ouvrez Shizuku → « Démarrer via le débogage sans fil » → « Association ». Shizuku affiche une notification pour saisir le code d'association.\n\n4. Dans les Options pour les développeurs, sous « Débogage sans fil », appuyez sur « Associer l'appareil avec un code d'association » et saisissez le code dans la notification de Shizuku.\n\n5. Appuyez sur « Démarrer » dans Shizuku. Terminé – retour à N-Connect.",
        ["1. Shizuku installieren"] = "1. Installer Shizuku",
        ["2. Shizuku starten"] = "2. Démarrer Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Autoriser l'accès à N-Connect",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>La première fois :</b> Maintenez le petit <b>bouton SYNC</b> rond de la manette jusqu'à ce que les voyants défilent. N-Connect la trouve automatiquement – vous n'avez rien à toucher.<br><br><b>Ensuite :</b> Appuyez simplement sur un bouton – la manette se reconnecte toute seule.<br><br><b>Joy-Con :</b> Connectez les deux l'un après l'autre. Ils sont automatiquement réunis en une seule manette (désactivable dans les paramètres).<br><br><b>Important :</b> Une manette ne mémorise qu'<b>un seul</b> appareil. Pour la réutiliser sur la Switch 2, appuyez à nouveau sur SYNC là-bas – puis de même sur le téléphone.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>La manette est introuvable :</b> Le Bluetooth est-il activé ? Avez-vous maintenu SYNC assez longtemps pour que les voyants défilent ? Si elle est connectée à la Switch ou à un PC, désactivez d'abord le Bluetooth là-bas.<br><br><b>Connectée, mais le jeu ne réagit pas :</b> La page des manettes doit afficher « Prêt » en haut. Si elle affiche « Shizuku n'est pas démarré », ouvrez Shizuku et appuyez sur Démarrer.<br><br><b>La connexion coupe en jouant :</b> Excluez N-Connect de l'optimisation de la batterie (Paramètres → Applications → N-Connect → Batterie → <i>Non restreinte</i>).<br><br><b>Entrées en double :</b> Si les commandes tactiles sont aussi activées et que le jeu prend en charge les manettes, désactivez le tactile.<br><br><b>La manette ne se reconnecte plus toute seule :</b> Appuyez une fois sur SYNC – elle mémorisera de nouveau cet appareil.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Configurer directement</b> place le dépôt dans Kodi (via {0}). Ensuite dans Kodi : <b>Extensions → Mes extensions → Dépôt d'extensions → DevCatSKZ Repository → Activer</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Télécharger</b> enregistre le fichier dans le dossier Téléchargements. Ensuite dans Kodi :<br><b>1.</b> Paramètres → Système → Extensions → activez <b>Sources inconnues</b>.<br><b>2.</b> Extensions → icône du paquet → <b>Installer depuis un fichier zip</b> → Download → <i>{0}</i>.<br><b>3.</b> « Installer depuis un dépôt » → <b>DevCatSKZ Repository</b>.",
        ["A (unten)"] = "A (bas)",
