    private static readonly Dictionary<string, string> It = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " Anche il controllo touch è attivo.",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Impostazioni → Informazioni sul telefono → tocca 7 volte «Numero build» (Opzioni sviluppatore attive).\n\n2. Connettiti a una rete Wi-Fi. Impostazioni → Sistema → Opzioni sviluppatore → attiva «Debug wireless».\n\n3. Apri Shizuku → «Avvia tramite debug wireless» → «Accoppiamento». Shizuku mostra una notifica per inserire il codice di accoppiamento.\n\n4. Nelle Opzioni sviluppatore, in «Debug wireless», tocca «Accoppia dispositivo con codice di accoppiamento» e digita il codice nella notifica di Shizuku.\n\n5. Tocca «Avvia» in Shizuku. Fatto: torna a N-Connect.",
        ["1. Shizuku installieren"] = "1. Installa Shizuku",
        ["2. Shizuku starten"] = "2. Avvia Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Consenti l'accesso a N-Connect",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>La prima volta:</b> Tieni premuto il piccolo <b>tasto SYNC</b> rotondo sul controller finché le luci scorrono avanti e indietro. N-Connect lo trova automaticamente: non devi toccare nulla.<br><br><b>Dopo:</b> Basta premere un tasto e il controller si riconnette da solo.<br><br><b>Joy-Con:</b> Collegali entrambi uno dopo l'altro. Vengono uniti automaticamente in un unico controller (disattivabile nelle impostazioni).<br><br><b>Importante:</b> Un controller ricorda sempre <b>un solo</b> dispositivo. Se vuoi usarlo di nuovo con la Switch 2, premi di nuovo SYNC lì, e poi anche sul telefono.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>Il controller non viene trovato:</b> Il Bluetooth è attivo? Hai tenuto premuto SYNC abbastanza a lungo da far scorrere le luci? Se è connesso alla Switch o a un PC, disattiva prima lì il Bluetooth.<br><br><b>Connesso, ma il gioco non reagisce:</b> Nella pagina dei controller in alto deve comparire «Pronto». Se compare «Shizuku non è avviato», apri Shizuku e tocca Avvia.<br><br><b>La connessione cade mentre giochi:</b> Escludi N-Connect dall'ottimizzazione della batteria (Impostazioni → App → N-Connect → Batteria → <i>Senza restrizioni</i>).<br><br><b>Input doppi:</b> Se anche il controllo touch è attivo e il gioco supporta i controller, disattiva il touch.<br><br><b>Il controller non si riconnette più da solo:</b> Premi SYNC una volta: memorizzerà di nuovo questo dispositivo.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Configura direttamente</b> mette il repository in Kodi (tramite {0}). Poi in Kodi: <b>Add-on → I miei add-on → Repository add-on → DevCatSKZ Repository → Abilita</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Scarica</b> salva il file nella cartella Download. Poi in Kodi:<br><b>1.</b> Impostazioni → Sistema → Add-on → attiva <b>Sorgenti sconosciute</b>.<br><b>2.</b> Add-on → icona del pacchetto → <b>Installa da file zip</b> → Download → <i>{0}</i>.<br><b>3.</b> «Installa da repository» → <b>DevCatSKZ Repository</b>.",
        ["A (unten)"] = "A (in basso)",
