        ["CONTROLLER"] = "CONTROLLER",
        ["Cemuhook/DSU-Server auf diesem Gerät (nur lokal): Dolphin, Citra & Co. erhalten Bewegung und Tasten."] = "Server Cemuhook/DSU su questo dispositivo (solo locale): Dolphin, Citra e altri ricevono movimento e pulsanti.",
        ["Controller"] = "Controller",
        ["Controller verbinden"] = "Connetti controller",
        ["Controller-Verbindung"] = "Connessione controller",
        ["DARSTELLUNG"] = "ASPETTO",
        ["Damit N-Connect erkennt, welches Spiel gerade läuft, erlaube einmal „Zugriff auf Nutzungsdaten“. Die App liest damit nur den Namen der App im Vordergrund – keine Inhalte."] = "Perché N-Connect riconosca il gioco in esecuzione, consenti una volta «Accesso ai dati di utilizzo». L'app legge solo il nome dell'app in primo piano, nessun contenuto.",
        ["Das Profil wird automatisch aktiv, solange „{0}“ läuft."] = "Il profilo si attiva automaticamente mentre «{0}» è in esecuzione.",
        ["Das Repository liegt jetzt in Kodi. Öffne Kodi und schalte es ein:\nAdd-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren.\n\nLäuft Kodi gerade, beende es vorher einmal ganz."] = "Il repository ora è in Kodi. Apri Kodi e abilitalo:\nAdd-on → I miei add-on → Repository add-on → DevCatSKZ Repository → Abilita.\n\nSe Kodi è aperto, chiudilo prima completamente.",
        ["Deine Controller erscheinen als echter Xbox-Controller in allen Spielen und Emulatoren. Kein Root nötig – du richtest einmal die kostenlose App Shizuku ein."] = "I tuoi controller appaiono come un vero controller Xbox in tutti i giochi ed emulatori. Niente root: configuri una volta l'app gratuita Shizuku.",
        ["Der Knopf öffnet direkt den Schalter für „N-Connect Touch-Steuerung“ – einschalten und zurückkehren."] = "Il pulsante apre direttamente l'interruttore di «Controllo touch di N-Connect»: attivalo e torna indietro.",
        ["Diagnose"] = "Diagnostica",
        ["Die Touch-Steuerung ist eine Bedienungshilfe. Sie führt nur Berührungen aus und liest keine Inhalte vom Bildschirm."] = "Il controllo touch è un servizio di accessibilità. Esegue solo tocchi e non legge alcun contenuto dello schermo.",
        ["Dieser Controller ist mit einem anderen Gerät gekoppelt (z. B. deiner Switch 2 oder einem PC). Drücke die SYNC-Taste, um ihn mit diesem Gerät zu verbinden."] = "Questo controller è associato a un altro dispositivo (ad es. la tua Switch 2 o un PC). Premi il tasto SYNC per collegarlo a questo dispositivo.",
        ["Direkt einrichten"] = "Configura direttamente",
        ["Direkt einrichten ging nicht – nutze „Herunterladen“."] = "La configurazione diretta non è riuscita: usa «Scarica».",
        ["Download fehlgeschlagen – Internetverbindung prüfen."] = "Download non riuscito: controlla la connessione a Internet.",
        ["Download fehlgeschlagen – bitte später erneut versuchen"] = "Scaricamento non riuscito – riprova più tardi",
        ["Drück eine Taste – sie erscheint hier."] = "Premi un tasto: apparirà qui.",
        ["Du kannst weitere Controller verbinden oder auf „Weiter“ tippen."] = "Puoi collegare altri controller o toccare «Avanti».",
        ["Dunkel"] = "Scuro",
        ["Echter Xbox-Controller für alle Spiele – ohne Root. Einmal kurz einrichten."] = "Vero controller Xbox per tutti i giochi, senza root. Configurazione rapida una tantum.",
        ["Echter Xbox-Controller für alle Spiele. Nur auf gerooteten Geräten."] = "Vero controller Xbox per tutti i giochi. Solo su dispositivi con root.",
        ["Eigene Tastenbelegungen, die automatisch zum laufenden Spiel passen."] = "Mappature personalizzate che si attivano automaticamente con il gioco.",
        ["Einen Moment – N-Connect übernimmt den Zugriff automatisch."] = "Un momento: N-Connect ottiene l'accesso automaticamente.",
        ["Eingabe: "] = "Input: ",
