    private static readonly Dictionary<string, string> Pt = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " O controlo tátil também está ligado.",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Definições → Acerca do telemóvel → toque 7× em «Número de compilação» (Opções de programador ativas).\n\n2. Ligue-se a uma rede Wi-Fi. Definições → Sistema → Opções de programador → ative «Depuração sem fios».\n\n3. Abra o Shizuku → «Iniciar através da depuração sem fios» → «Emparelhamento». O Shizuku mostra uma notificação para introduzir o código de emparelhamento.\n\n4. Nas Opções de programador, em «Depuração sem fios», toque em «Sincronizar dispositivo com código de sincronização» e introduza o código na notificação do Shizuku.\n\n5. Toque em «Iniciar» no Shizuku. Pronto – volte ao N-Connect.",
        ["1. Shizuku installieren"] = "1. Instalar o Shizuku",
        ["2. Shizuku starten"] = "2. Iniciar o Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Permitir o acesso ao N-Connect",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>Da primeira vez:</b> Mantenha premido o pequeno <b>botão SYNC</b> redondo do comando até as luzes correrem de um lado para o outro. O N-Connect encontra-o automaticamente – não precisa de tocar em nada.<br><br><b>Depois:</b> Basta premir um botão – o comando volta a ligar-se sozinho.<br><br><b>Joy-Con:</b> Ligue os dois um após o outro. São automaticamente combinados num só comando (pode desativar nas definições).<br><br><b>Importante:</b> Um comando lembra-se sempre de <b>um só</b> dispositivo. Para o voltar a usar na Switch 2, prima SYNC lá – e depois também no telemóvel.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>O comando não é encontrado:</b> O Bluetooth está ligado? Manteve SYNC premido tempo suficiente até as luzes correrem? Se estiver ligado à Switch ou a um PC, desligue primeiro o Bluetooth lá.<br><br><b>Ligado, mas o jogo não reage:</b> Na página dos comandos tem de aparecer «Pronto» no topo. Se aparecer «O Shizuku não está iniciado», abra o Shizuku e toque em Iniciar.<br><br><b>A ligação cai durante o jogo:</b> Exclua o N-Connect da otimização da bateria (Definições → Apps → N-Connect → Bateria → <i>Sem restrições</i>).<br><br><b>Entradas duplicadas:</b> Se o controlo tátil também estiver ligado e o jogo suportar comandos, desligue o tátil.<br><br><b>O comando já não se liga sozinho:</b> Prima SYNC uma vez – volta a memorizar este dispositivo.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Configurar diretamente</b> coloca o repositório no Kodi (através de {0}). Depois no Kodi: <b>Add-ons → Os meus add-ons → Repositório de add-ons → DevCatSKZ Repository → Ativar</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Transferir</b> guarda o ficheiro na pasta Transferências. Depois no Kodi:<br><b>1.</b> Definições → Sistema → Add-ons → ative <b>Fontes desconhecidas</b>.<br><b>2.</b> Add-ons → ícone do pacote → <b>Instalar a partir de ficheiro zip</b> → Download → <i>{0}</i>.<br><b>3.</b> «Instalar a partir de repositório» → <b>DevCatSKZ Repository</b>.",
        ["A (unten)"] = "A (em baixo)",
