    private static readonly Dictionary<string, string> Nl = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " Aanraakbediening staat ook aan.",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Instellingen → Over de telefoon → tik 7× op ‘Buildnummer’ (ontwikkelaarsopties aan).\n\n2. Maak verbinding met een wifi-netwerk. Instellingen → Systeem → Ontwikkelaarsopties → zet ‘Draadloze foutopsporing’ aan.\n\n3. Open Shizuku → ‘Starten via draadloze foutopsporing’ → ‘Koppelen’. Shizuku toont een melding om de koppelingscode in te voeren.\n\n4. Tik in de Ontwikkelaarsopties onder ‘Draadloze foutopsporing’ op ‘Apparaat koppelen met koppelingscode’ en typ de code in de Shizuku-melding.\n\n5. Tik in Shizuku op ‘Starten’. Klaar – terug naar N-Connect.",
        ["1. Shizuku installieren"] = "1. Shizuku installeren",
        ["2. Shizuku starten"] = "2. Shizuku starten",
        ["3. N-Connect den Zugriff erlauben"] = "3. N-Connect toegang geven",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>De eerste keer:</b> Houd de kleine ronde <b>SYNC-knop</b> op de controller ingedrukt tot de lampjes heen en weer lopen. N-Connect vindt hem automatisch – je hoeft niets aan te tikken.<br><br><b>Daarna:</b> Druk gewoon op een knop – de controller maakt vanzelf weer verbinding.<br><br><b>Joy-Con:</b> Verbind ze allebei na elkaar. Ze worden automatisch samengevoegd tot één controller (uit te schakelen in de instellingen).<br><br><b>Belangrijk:</b> Een controller onthoudt altijd maar <b>één</b> apparaat. Wil je hem weer op de Switch 2 gebruiken, druk daar dan opnieuw op SYNC – en daarna op de telefoon ook.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>Controller wordt niet gevonden:</b> Staat Bluetooth aan? SYNC lang genoeg ingedrukt tot de lampjes lopen? Is hij nu met de Switch of een pc verbonden, zet daar dan eerst Bluetooth uit.<br><br><b>Verbonden, maar de game reageert niet:</b> Op de controllerpagina moet bovenaan ‘Klaar’ staan. Staat daar ‘Shizuku is niet gestart’, open dan Shizuku en tik op Starten.<br><br><b>Verbinding valt weg tijdens het spelen:</b> Sluit N-Connect uit van batterijoptimalisatie (Instellingen → Apps → N-Connect → Batterij → <i>Onbeperkt</i>).<br><br><b>Dubbele invoer:</b> Staat de aanraakbediening ook aan en ondersteunt de game controllers, zet aanraken dan uit.<br><br><b>Controller maakt niet meer vanzelf verbinding:</b> Druk één keer op SYNC – dan onthoudt hij dit apparaat opnieuw.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Direct instellen</b> plaatst de repository in Kodi (via {0}). Daarna in Kodi: <b>Add-ons → Mijn add-ons → Add-on-repository → DevCatSKZ Repository → Inschakelen</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Downloaden</b> slaat het bestand op in de map Downloads. Daarna in Kodi:<br><b>1.</b> Instellingen → Systeem → Add-ons → zet <b>Onbekende bronnen</b> aan.<br><b>2.</b> Add-ons → pakketpictogram → <b>Installeren via zip-bestand</b> → Download → <i>{0}</i>.<br><b>3.</b> ‘Installeren via repository’ → <b>DevCatSKZ Repository</b>.",
        ["A (unten)"] = "A (onder)",
