        ["N-Connect Spieler {0}"] = "N-Connect Speler {0}",
        ["N-Connect Touch-Steuerung"] = "N-Connect aanraakbediening",
        ["N-Connect braucht die Berechtigung „Geräte in der Nähe“, um deine Controller zu finden."] = "N-Connect heeft de toestemming ‘Apparaten in de buurt’ nodig om je controllers te vinden.",
