    private static readonly Dictionary<string, string> Pl = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " Sterowanie dotykowe jest też włączone.",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Ustawienia → Informacje o telefonie → stuknij 7× „Numer kompilacji” (opcje programisty włączone).\n\n2. Połącz się z siecią Wi-Fi. Ustawienia → System → Opcje programisty → włącz „Debugowanie bezprzewodowe”.\n\n3. Otwórz Shizuku → „Uruchom przez debugowanie bezprzewodowe” → „Parowanie”. Shizuku pokaże powiadomienie do wpisania kodu parowania.\n\n4. W Opcjach programisty w „Debugowanie bezprzewodowe” stuknij „Sparuj urządzenie za pomocą kodu parowania” i wpisz kod w powiadomieniu Shizuku.\n\n5. Stuknij „Uruchom” w Shizuku. Gotowe – wróć do N-Connect.",
        ["1. Shizuku installieren"] = "1. Zainstaluj Shizuku",
        ["2. Shizuku starten"] = "2. Uruchom Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Zezwól N-Connect na dostęp",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>Za pierwszym razem:</b> Przytrzymaj mały okrągły <b>przycisk SYNC</b> na kontrolerze, aż diody zaczną biegać w tę i z powrotem. N-Connect znajdzie go automatycznie – nie musisz niczego stukać.<br><br><b>Później:</b> Wystarczy nacisnąć przycisk – kontroler sam połączy się ponownie.<br><br><b>Joy-Con:</b> Połącz oba po kolei. Zostaną automatycznie połączone w jeden kontroler (można to wyłączyć w ustawieniach).<br><br><b>Ważne:</b> Kontroler pamięta zawsze tylko <b>jedno</b> urządzenie. Jeśli chcesz znów używać go z Switch 2, naciśnij tam ponownie SYNC – a potem tak samo na telefonie.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>Kontroler nie zostaje znaleziony:</b> Czy Bluetooth jest włączony? Czy przytrzymano SYNC wystarczająco długo, aż diody zaczną biegać? Jeśli jest właśnie połączony ze Switch lub komputerem, najpierw wyłącz tam Bluetooth.<br><br><b>Połączony, ale gra nie reaguje:</b> Na stronie kontrolerów u góry musi być „Gotowe”. Jeśli jest tam „Shizuku nie jest uruchomione”, otwórz Shizuku i stuknij Uruchom.<br><br><b>Połączenie zrywa się podczas gry:</b> Wyłącz N-Connect z optymalizacji baterii (Ustawienia → Aplikacje → N-Connect → Bateria → <i>Bez ograniczeń</i>).<br><br><b>Podwójne wejścia:</b> Jeśli sterowanie dotykowe jest dodatkowo włączone, a gra obsługuje kontrolery, wyłącz dotyk.<br><br><b>Kontroler nie łączy się już sam:</b> Naciśnij raz SYNC – wtedy ponownie zapamięta to urządzenie.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Skonfiguruj bezpośrednio</b> umieszcza repozytorium w Kodi (przez {0}). Potem w Kodi: <b>Dodatki → Moje dodatki → Repozytorium dodatków → DevCatSKZ Repository → Włącz</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Pobierz</b> zapisuje plik w folderze Pobrane. Potem w Kodi:<br><b>1.</b> Ustawienia → System → Dodatki → włącz <b>Nieznane źródła</b>.<br><b>2.</b> Dodatki → ikona paczki → <b>Instaluj z pliku zip</b> → Download → <i>{0}</i>.<br><b>3.</b> „Instaluj z repozytorium” → <b>DevCatSKZ Repository</b>.",
