        ["Keine Ausgabe eingerichtet"] = "Nie skonfigurowano wyjścia",
        ["Keine Einrichtung außer einer Bedienungshilfe. Tasten werden zu Bildschirmberührungen – für Spiele ohne Controller-Unterstützung. Etwas mehr Verzögerung, kein echter Controller."] = "Bez konfiguracji poza usługą ułatwień dostępu. Przyciski stają się dotknięciami ekranu – dla gier bez obsługi kontrolerów. Nieco większe opóźnienie, brak prawdziwego kontrolera.",
        ["Kodi installieren"] = "Zainstaluj Kodi",
        ["Kodi ist auf diesem Gerät nicht installiert."] = "Kodi nie jest zainstalowane na tym urządzeniu.",
