        ["Linker und rechter Joy-Con 2 ergeben zusammen einen Spieler – wie an der Switch."] = "Lewy i prawy Joy-Con 2 tworzą razem jednego gracza – jak na Switch.",
        ["Los geht's"] = "Zaczynamy",
        ["Lässt sich auch zusätzlich zu Shizuku oder Root einschalten."] = "Można je też włączyć dodatkowo do Shizuku lub roota.",
        ["Läuft."] = "Działa.",
        ["Mehr Infos"] = "Więcej informacji",
        ["Mit Android starten"] = "Uruchamiaj z Androidem",
        ["Mit Root nutzen"] = "Używaj z rootem",
        ["Mit Shizuku oder Root liest N-Connect die Adresse selbst aus. Sonst findest du sie unter Einstellungen → Über das Telefon → Bluetooth-Adresse."] = "Z Shizuku lub rootem N-Connect sam odczytuje adres. W przeciwnym razie znajdziesz go w Ustawienia → Informacje o telefonie → Adres Bluetooth.",
        ["Mit einem anderen Gerät gekoppelt – SYNC drücken, um ihn hier zu nutzen"] = "Sparowany z innym urządzeniem – naciśnij SYNC, aby użyć go tutaj",
        ["N-Connect Spieler {0}"] = "N-Connect Gracz {0}",
        ["N-Connect Touch-Steuerung"] = "Sterowanie dotykowe N-Connect",
        ["N-Connect braucht die Berechtigung „Geräte in der Nähe“, um deine Controller zu finden."] = "N-Connect potrzebuje uprawnienia „Urządzenia w pobliżu”, aby znaleźć twoje kontrolery.",
