        ["Nicht eingeschränkt – die Verbindung bleibt beim Spielen stabil."] = "Bez ograniczeń – połączenie pozostaje stabilne podczas gry.",
        ["Nicht einschränken"] = "Nie ograniczaj",
        ["Nicht verbunden – eine Taste am Controller drücken"] = "Niepołączony – naciśnij przycisk na kontrolerze",
        ["Nimmt den besten verfügbaren Weg: Root, sonst Shizuku, sonst Touch."] = "Wybiera najlepszą dostępną metodę: root, w przeciwnym razie Shizuku, a w ostateczności dotyk.",
        ["Noch kein Ausgabeweg eingerichtet"] = "Nie skonfigurowano jeszcze metody wyjścia",
