    private static readonly Dictionary<string, string> Ru = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " Сенсорное управление тоже включено.",
        [" · {0} MB"] = " · {0} МБ",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. Настройки → О телефоне → 7 раз нажмите «Номер сборки» (режим разработчика включён).\n\n2. Подключитесь к сети Wi-Fi. Настройки → Система → Для разработчиков → включите «Отладку по Wi-Fi».\n\n3. Откройте Shizuku → «Запуск через отладку по Wi-Fi» → «Сопряжение». Shizuku покажет уведомление для ввода кода сопряжения.\n\n4. В разделе «Для разработчиков» → «Отладка по Wi-Fi» нажмите «Подключить устройство с помощью кода подключения» и введите код в уведомлении Shizuku.\n\n5. Нажмите «Запустить» в Shizuku. Готово – вернитесь в N-Connect.",
        ["1. Shizuku installieren"] = "1. Установить Shizuku",
        ["2. Shizuku starten"] = "2. Запустить Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. Разрешить доступ N-Connect",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>В первый раз:</b> Удерживайте маленькую круглую <b>кнопку SYNC</b> на контроллере, пока огоньки не побегут туда-сюда. N-Connect найдёт его автоматически – ничего нажимать не нужно.<br><br><b>Потом:</b> Просто нажмите любую кнопку – контроллер сам подключится снова.<br><br><b>Joy-Con:</b> Подключите оба по очереди. Они автоматически объединяются в один контроллер (можно отключить в настройках).<br><br><b>Важно:</b> Контроллер помнит только <b>одно</b> устройство. Чтобы снова использовать его с Switch 2, нажмите там SYNC – а потом так же на телефоне.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>Контроллер не находится:</b> Bluetooth включён? Кнопку SYNC удерживали достаточно долго, пока не побежали огоньки? Если он сейчас подключён к Switch или ПК, сначала выключите там Bluetooth.<br><br><b>Подключён, но игра не реагирует:</b> На странице контроллеров вверху должно быть «Готово». Если там написано «Shizuku не запущен», откройте Shizuku и нажмите «Запустить».<br><br><b>Связь обрывается во время игры:</b> Исключите N-Connect из оптимизации батареи (Настройки → Приложения → N-Connect → Батарея → <i>Без ограничений</i>).<br><br><b>Двойной ввод:</b> Если сенсорное управление тоже включено, а игра поддерживает контроллеры, выключите сенсорное управление.<br><br><b>Контроллер больше не подключается сам:</b> Нажмите один раз SYNC – он снова запомнит это устройство.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>Настроить напрямую</b> помещает репозиторий в Kodi (через {0}). Затем в Kodi: <b>Дополнения → Мои дополнения → Репозиторий дополнений → DevCatSKZ Repository → Включить</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>Скачать</b> сохраняет файл в папку «Загрузки». Затем в Kodi:<br><b>1.</b> Настройки → Система → Дополнения → включите <b>Неизвестные источники</b>.<br><b>2.</b> Дополнения → значок пакета → <b>Установить из ZIP-файла</b> → Download → <i>{0}</i>.<br><b>3.</b> «Установить из репозитория» → <b>DevCatSKZ Repository</b>.",
