    private static readonly Dictionary<string, string> Ja = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " タッチ操作もオンです。",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. 設定 → デバイス情報 →「ビルド番号」を 7 回タップ（開発者向けオプションが有効に）。\n\n2. Wi-Fi に接続します。設定 → システム → 開発者向けオプション →「ワイヤレス デバッグ」をオン。\n\n3. Shizuku を開く →「ワイヤレス デバッグで起動」→「ペアリング」。Shizuku にペア設定コード入力用の通知が表示されます。\n\n4. 開発者向けオプションの「ワイヤレス デバッグ」で「ペア設定コードによるデバイスのペア設定」をタップし、表示されたコードを Shizuku の通知に入力します。\n\n5. Shizuku で「開始」をタップ。完了 – N-Connect に戻ります。",
        ["1. Shizuku installieren"] = "1. Shizuku をインストール",
        ["2. Shizuku starten"] = "2. Shizuku を開始",
        ["3. N-Connect den Zugriff erlauben"] = "3. N-Connect にアクセスを許可",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>初回：</b>コントローラーの小さな丸い <b>SYNC ボタン</b> を、ランプが左右に流れるまで長押しします。N-Connect が自動的に見つけるので、何もタップする必要はありません。<br><br><b>2 回目以降：</b>ボタンを押すだけで、コントローラーが自動的に再接続します。<br><br><b>Joy-Con：</b>2 本を順番に接続します。自動的に 1 台のコントローラーにまとめられます（設定でオフにできます）。<br><br><b>重要：</b>コントローラーが記憶できる機器は常に <b>1 台</b> だけです。Switch 2 で再び使うには、そちらで SYNC を押してください – その後スマートフォンでも同様です。",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>コントローラーが見つからない：</b>Bluetooth はオンですか？ランプが流れるまで SYNC を十分長く押しましたか？Switch や PC に接続中の場合は、先にそちらの Bluetooth をオフにしてください。<br><br><b>接続されたがゲームが反応しない：</b>コントローラーページの上部に「準備完了」と表示されている必要があります。「Shizuku が起動していません」と表示されている場合は、Shizuku を開いて開始をタップしてください。<br><br><b>プレイ中に接続が切れる：</b>N-Connect をバッテリー最適化の対象外にしてください（設定 → アプリ → N-Connect → バッテリー → <i>制限なし</i>）。<br><br><b>入力が二重になる：</b>タッチ操作も有効で、ゲームがコントローラーに対応している場合は、タッチをオフにしてください。<br><br><b>コントローラーが自動で再接続しなくなった：</b>SYNC を一度押すと、この機器を再び記憶します。",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>直接設定</b> はリポジトリを Kodi に配置します（{0} 経由）。その後 Kodi で：<b>アドオン → マイアドオン → アドオンリポジトリ → DevCatSKZ Repository → 有効</b>。<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>ダウンロード</b> はファイルを Download フォルダーに保存します。その後 Kodi で：<br><b>1.</b> 設定 → システム → アドオン → <b>不明なソース</b> をオンにします。<br><b>2.</b> アドオン → パッケージアイコン → <b>Zip ファイルからインストール</b> → Download → <i>{0}</i>。<br><b>3.</b> 「リポジトリからインストール」→ <b>DevCatSKZ Repository</b>。",
