    private static readonly Dictionary<string, string> Zh = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " 触控操作也已开启。",
        [" · {0} MB"] = " · {0} MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. 设置 → 关于手机 → 点按“版本号”7 次（开启开发者选项）。\n\n2. 连接到 WLAN。设置 → 系统 → 开发者选项 → 开启“无线调试”。\n\n3. 打开 Shizuku →“通过无线调试启动”→“配对”。Shizuku 会显示一条用于输入配对码的通知。\n\n4. 在开发者选项的“无线调试”中点按“使用配对码配对设备”，并把配对码输入到 Shizuku 的通知中。\n\n5. 在 Shizuku 中点按“启动”。完成 – 返回 N-Connect。",
        ["1. Shizuku installieren"] = "1. 安装 Shizuku",
        ["2. Shizuku starten"] = "2. 启动 Shizuku",
        ["3. N-Connect den Zugriff erlauben"] = "3. 允许 N-Connect 访问",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>首次使用：</b>按住控制器上的小圆形 <b>SYNC 按钮</b>，直到指示灯来回闪动。N-Connect 会自动找到它 – 你无需点按任何东西。<br><br><b>之后：</b>只需按下任意按键，控制器就会自动重新连接。<br><br><b>Joy-Con：</b>依次连接两只。它们会自动合并为一个控制器（可在设置中关闭）。<br><br><b>重要：</b>控制器始终只记住 <b>一台</b> 设备。若想再次在 Switch 2 上使用，请在那里重新按 SYNC – 之后在手机上也一样。",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>找不到控制器：</b>蓝牙开了吗？SYNC 是否按得足够久，直到指示灯闪动？如果它正连接着 Switch 或电脑，请先关闭那边的蓝牙。<br><br><b>已连接，但游戏没有反应：</b>控制器页面顶部必须显示“就绪”。如果显示“Shizuku 未启动”，请打开 Shizuku 并点按启动。<br><br><b>游戏时连接中断：</b>请将 N-Connect 从电池优化中排除（设置 → 应用 → N-Connect → 电池 → <i>无限制</i>）。<br><br><b>输入重复：</b>如果同时开启了触控操作，而游戏支持控制器，请关闭触控。<br><br><b>控制器不再自动重新连接：</b>按一次 SYNC – 它会重新记住这台设备。",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>直接设置</b> 会把存储库放入 Kodi（通过 {0}）。然后在 Kodi 中：<b>附加组件 → 我的附加组件 → 附加组件存储库 → DevCatSKZ Repository → 启用</b>。<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>下载</b> 会把文件保存到 Download 文件夹。然后在 Kodi 中：<br><b>1.</b> 设置 → 系统 → 附加组件 → 开启 <b>未知来源</b>。<br><b>2.</b> 附加组件 → 包图标 → <b>从 zip 文件安装</b> → Download → <i>{0}</i>。<br><b>3.</b> “从存储库安装” → <b>DevCatSKZ Repository</b>。",
