    private static readonly Dictionary<string, string> Ko = new(StringComparer.Ordinal)
    {
        [" Touch-Steuerung ist zusätzlich an."] = " 터치 조작도 켜져 있습니다.",
        [" · {0} MB"] = " · {0}MB",
        ["1. Einstellungen → Über das Telefon → 7× auf „Build-Nummer“ tippen (Entwickleroptionen an).\n\n2. Mit einem WLAN verbinden. Einstellungen → System → Entwickleroptionen → „Kabelloses Debugging“ einschalten.\n\n3. Shizuku öffnen → „Über kabelloses Debugging starten“ → „Kopplung“. Shizuku zeigt eine Benachrichtigung zum Eingeben des Kopplungscodes.\n\n4. In den Entwickleroptionen unter „Kabelloses Debugging“ → „Gerät über Kopplungscode koppeln“ tippen und den Code in die Shizuku-Benachrichtigung eintippen.\n\n5. In Shizuku auf „Starten“ tippen. Fertig – zurück zu N-Connect."] = "1. 설정 → 휴대전화 정보 → '빌드 번호'를 7번 탭(개발자 옵션 켜짐).\n\n2. Wi-Fi에 연결하세요. 설정 → 시스템 → 개발자 옵션 → '무선 디버깅'을 켜세요.\n\n3. Shizuku 열기 → '무선 디버깅으로 시작' → '페어링'. Shizuku가 페어링 코드 입력용 알림을 표시합니다.\n\n4. 개발자 옵션의 '무선 디버깅'에서 '페어링 코드로 기기 페어링'을 탭하고 코드를 Shizuku 알림에 입력하세요.\n\n5. Shizuku에서 '시작'을 탭하세요. 완료 – N-Connect로 돌아가세요.",
        ["1. Shizuku installieren"] = "1. Shizuku 설치",
        ["2. Shizuku starten"] = "2. Shizuku 시작",
        ["3. N-Connect den Zugriff erlauben"] = "3. N-Connect에 액세스 허용",
        ["<b>Beim ersten Mal:</b> Halte die kleine runde <b>SYNC-Taste</b> am Controller gedrückt, bis die Lichter hin- und herlaufen. N-Connect findet ihn automatisch – du musst nichts antippen.<br><br><b>Danach:</b> Einfach eine Taste drücken – der Controller verbindet sich von selbst wieder.<br><br><b>Joy-Con:</b> Verbinde beide nacheinander. Sie werden automatisch zu einem Controller zusammengefasst (abschaltbar in den Einstellungen).<br><br><b>Wichtig:</b> Ein Controller merkt sich immer nur <b>ein</b> Gerät. Willst du ihn wieder an der Switch 2 nutzen, drücke dort erneut SYNC – danach am Handy ebenfalls."] = "<b>처음:</b> 컨트롤러의 작고 둥근 <b>SYNC 버튼</b>을 표시등이 좌우로 움직일 때까지 길게 누르세요. N-Connect가 자동으로 찾아내므로 아무것도 탭할 필요가 없습니다.<br><br><b>그 후:</b> 버튼만 누르면 컨트롤러가 자동으로 다시 연결됩니다.<br><br><b>Joy-Con:</b> 두 개를 차례로 연결하세요. 자동으로 하나의 컨트롤러로 합쳐집니다(설정에서 끌 수 있음).<br><br><b>중요:</b> 컨트롤러는 항상 <b>한 대</b>의 기기만 기억합니다. Switch 2에서 다시 사용하려면 그곳에서 SYNC를 다시 누르세요 – 그 후 휴대전화에서도 마찬가지입니다.",
        ["<b>Controller wird nicht gefunden:</b> Bluetooth an? SYNC-Taste lange genug gedrückt, bis die Lichter laufen? Ist er gerade mit der Switch oder einem PC verbunden, schalte dort zuerst Bluetooth aus.<br><br><b>Verbunden, aber das Spiel reagiert nicht:</b> Auf der Controller-Startseite muss oben „Bereit“ stehen. Steht dort „Shizuku ist nicht gestartet“, öffne Shizuku und tippe auf Starten.<br><br><b>Verbindung bricht beim Spielen ab:</b> Nimm N-Connect in den Akku-Einstellungen von der Optimierung aus (Einstellungen → Apps → N-Connect → Akku → <i>Nicht eingeschränkt</i>).<br><br><b>Doppelte Eingaben:</b> Ist Touch-Steuerung zusätzlich an und das Spiel unterstützt Controller, schalte Touch aus.<br><br><b>Controller verbindet sich nicht mehr von selbst:</b> Einmal SYNC drücken – dann merkt er sich dieses Gerät neu."] = "<b>컨트롤러를 찾을 수 없음:</b> 블루투스가 켜져 있나요? 표시등이 움직일 때까지 SYNC를 충분히 길게 눌렀나요? Switch나 PC에 연결되어 있다면 먼저 그쪽의 블루투스를 끄세요.<br><br><b>연결됐지만 게임이 반응하지 않음:</b> 컨트롤러 페이지 상단에 '준비됨'이 표시되어야 합니다. 'Shizuku가 시작되지 않음'이 표시되면 Shizuku를 열고 시작을 탭하세요.<br><br><b>게임 중 연결이 끊김:</b> N-Connect를 배터리 최적화에서 제외하세요(설정 → 애플리케이션 → N-Connect → 배터리 → <i>제한 없음</i>).<br><br><b>입력이 중복됨:</b> 터치 조작도 켜져 있고 게임이 컨트롤러를 지원한다면 터치를 끄세요.<br><br><b>컨트롤러가 더 이상 자동으로 연결되지 않음:</b> SYNC를 한 번 누르면 이 기기를 다시 기억합니다.",
        ["<b>Direkt einrichten</b> legt das Repository in Kodi ab (über {0}). Danach in Kodi: <b>Add-ons → Meine Add-ons → Add-on-Repository → DevCatSKZ Repository → Aktivieren</b>.<br><br>"] = "<b>바로 설정</b>은 저장소를 Kodi에 넣습니다({0} 사용). 그런 다음 Kodi에서: <b>애드온 → 내 애드온 → 애드온 저장소 → DevCatSKZ Repository → 사용</b>.<br><br>",
        ["<b>Herunterladen</b> speichert die Datei im Download-Ordner. Danach in Kodi:<br><b>1.</b> Einstellungen → System → Add-ons → <b>Unbekannte Quellen</b> einschalten.<br><b>2.</b> Add-ons → Paket-Symbol → <b>Aus ZIP-Datei installieren</b> → Download → <i>{0}</i>.<br><b>3.</b> „Aus Repository installieren“ → <b>DevCatSKZ Repository</b>."] = "<b>다운로드</b>는 파일을 Download 폴더에 저장합니다. 그런 다음 Kodi에서:<br><b>1.</b> 설정 → 시스템 → 애드온 → <b>알 수 없는 출처</b>를 켜세요.<br><b>2.</b> 애드온 → 패키지 아이콘 → <b>zip 파일에서 설치</b> → Download → <i>{0}</i>.<br><b>3.</b> '저장소에서 설치' → <b>DevCatSKZ Repository</b>.",
